referenceSolutions.python:
def undoDrawerPositiveInkInvoice(readings):
    a=readings
    out=[]
    for x in a:
        if x>=0: out.append(x)
        else:
            for _ in range(min(-x,len(out))): out.pop()
    return sum(x for x in out if x>0)

